    try{
        if(function_exists('csrf_check'))csrf_check();$action=(string)($_POST['action']??'');
        if($action==='channel'){
            sk1330nc_set_channel((string)($_POST['channel_key']??''),$_POST);$msg='Notification channel policy saved.';
            if(function_exists('sk1300_audit'))sk1300_audit('notification_control.channel',0,(string)($_POST['channel_key']??''),['enabled'=>!empty($_POST['enabled'])]);
        }elseif($action==='rule'){
            sk1330nc_set_rule($_POST);$msg='Notification event rule saved.';
            if(function_exists('sk1300_audit'))sk1300_audit('notification_control.rule',0,(string)($_POST['event_key']??''),['channel'=>(string)($_POST['channel_key']??'')]);
        }elseif($action==='delete_rule'){
            sk1330nc_delete_rule((string)($_POST['event_key']??''),(string)($_POST['channel_key']??''));$msg='Notification event rule removed.';
        }
    }catch(Throwable $e){$err=$e->getMessage();}
}
$r=sk1330nc_snapshot();$s=$r['summary'];$csrf=function_exists('csrf_token')?csrf_token():'';
